(function(){
 'use strict';
 const C=Stratum,TC=TrainingContent,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const STORE='stratum-training-v3';let state=C.defaults(),page='overview',filter='All',search='',chartSkill='all',queue=[],active=null,range=null,decisionTimer=null,scenario=null,storageOK=true,lastFocus=null;
 const icon=(name,size=20)=>{const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',crosshair:'M12 2v4m0 12v4M2 12h4m12 0h4M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',bolt:'m13 2-8 12h6l-1 8 9-13h-6z',wave:'M2 12c3-12 5 12 9 0s6 12 11 0',layers:'m12 3 10 6-10 6L2 9zm-9 11 9 6 9-6',focus:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 12h8',arrows:'m7 7-5 5 5 5m-5-5h20m-5-5 5 5-5 5',bars:'M4 8h4v8H4zm6-3h4v14h-4zm6 5h4v4h-4z',corner:'M4 20V4h16M4 12h8v8',hex:'m12 2 9 5v10l-9 5-9-5V7zM8 12h8',coins:'M20 7c0 3-16 3-16 0s16-3 16 0zM4 7v10c0 3 16 3 16 0V7M4 12c0 3 16 3 16 0',radar:'M12 3a9 9 0 1 0 9 9M12 12V2m0 10 8-8M7 12a5 5 0 1 0 5-5',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8m-6 9v-3c0-5 12-5 12 0v3m2-16a4 4 0 0 1 0 7m1 3c3 0 5 1 5 4v2',map:'m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3zm6-3v17m8-14v17',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l4 2',chat:'M3 3h18v14H9l-6 4zM7 8h10M7 12h6',pulse:'M2 12h5l3-8 4 16 3-8h5',branch:'M6 3v12a5 5 0 0 0 5 5h7m-12-8h6a5 5 0 0 0 5-5V3M3 3h6m5 0h6m-2 14 3 3-3 3',chart:'M3 3v18h18M6 16l5-6 4 3 6-8',sliders:'M5 3v18m7-18v18m7-18v18M2 8h6m1 8h6m1-10h6',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m4 12 5 5L20 6',play:'m8 4 12 8-12 8z',plus:'M12 4v16M4 12h16',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',close:'m5 5 14 14M19 5 5 19'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.crosshair}"/></svg>`;};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmtDate=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
 const fmtTime=n=>`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`;
 const skillBy=id=>C.skills.find(s=>s.id===id);
 const gameName=()=>state.settings.game==='cs2'?'Counter-Strike 2':'VALORANT';
 const modeName=()=>C.inputMode(state.settings)==='touch'?'Touch':'Mouse & keyboard';
 const methodName=()=>((typeof WeaponData!=='undefined'?(WeaponData.byId(state.settings.loadout?.[state.settings.game])||WeaponData.byId(WeaponData.defaults[state.settings.game]))?.name+' · ':'')+(C.inputMode(state.settings)==='touch'?'Touch look':state.settings.interaction==='direct'?'Mouse capture':'Drag look'));
 const button=(text,action,cls='primary',extra='')=>`<button class="button ${cls}" ${action} ${extra}>${text}</button>`;
 function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toast-region').replaceChildren(node);setTimeout(()=>node.remove(),5500);}
 function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Device storage is unavailable or full. Export a backup to keep this session.',true);}$('#save-status').innerHTML=storageOK?'<i></i> Saved on this device':'<i class="bad"></i> Unsaved · export a backup';}
 function applySettings(){document.documentElement.style.setProperty('--accent',state.settings.accent);const rgb=state.settings.accent.slice(1).match(/../g).map(x=>parseInt(x,16));const lum=a=>a.map(x=>{x/=255;return x<=.04045?x/12.92:((x+.055)/1.055)**2.4;}).reduce((v,x,i)=>v+x*[.2126,.7152,.0722][i],0);const l=lum(rgb);document.documentElement.style.setProperty('--accent-ink',l>.179?'#111111':'#ffffff');const light=state.settings.theme==='light';let accessible=[...rgb],bg=light?.94:.014;for(let i=0;i<60&&(Math.max(lum(accessible),bg)+.05)/(Math.min(lum(accessible),bg)+.05)<4.5;i++)accessible=accessible.map(x=>light?Math.max(0,x-4):Math.min(255,x+4));document.documentElement.style.setProperty('--accent-text','rgb('+accessible.join(',')+')');document.documentElement.dataset.theme=state.settings.theme;document.documentElement.dataset.density=state.settings.density;document.documentElement.dataset.corners=state.settings.corners;document.documentElement.dataset.game=state.settings.game;const toggle=$('#theme-toggle');if(toggle){toggle.textContent=light?'Dark mode':'Light mode';toggle.setAttribute('aria-pressed',String(light));}document.documentElement.classList.toggle('reduced',state.settings.reduced);}
 try{const data=localStorage.getItem(STORE);if(data)state=C.validate(JSON.parse(data));}catch{storageOK=false;setTimeout(()=>toast('Saved data could not be loaded. A fresh profile is open; the previous stored data has not been overwritten.',true),500);}
 const nav=[['overview','grid','Overview'],['training','crosshair','Training lab'],['scenarios','branch','Round scenarios'],['progress','chart','Your progress'],['settings','sliders','Customize']];
 function renderNav(){ $('#nav').innerHTML=`<div class="nav-caption">YOUR WORKSPACE</div>`+nav.map(([id,i,label])=>`<a href="#${id}" aria-label="${label}" class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='training'?'<small>16</small>':''}</a>`).join('');$$('[data-game]').forEach(b=>{const on=b.dataset.game===state.settings.game;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});$('#mobile-game').value=state.settings.game;$('#page-label').textContent=nav.find(x=>x[0]===page)?.[2]||'Training lab';}
 function top(title,subtitle,actions='',plain=false){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
 function navigate(p){if(active||scenario){toast('Finish or exit the active session before changing pages.');return;}page=nav.some(x=>x[0]===p)?p:'overview';render();}
 function render(){applySettings();renderNav();if(active){renderActive();return;}if(scenario){renderScenario();return;}const views={overview:overview,training:training,scenarios:scenarioList,progress:progress,settings:settings};$('#main').innerHTML=views[page]();wireInputs();}
 function stats(){const o=C.overall(state),rows=C.records(state),minutes=Math.round(rows.reduce((a,b)=>a+(b.countTime===false?0:b.duration),0)/60),today=rows.filter(x=>new Date(x.at).toDateString()===new Date().toDateString()).length;return `<div class="stat-grid"><article class="stat-card"><span>TRAINER PROFICIENCY ${icon('pulse',16)}</span><div>${o.value===null?'—':o.value}<small>/ 100</small></div><p>${C.tier(o.value)} <b>· ${o.count}/16 measured</b></p></article><article class="stat-card"><span>SKILLS MAPPED ${icon('radar',16)}</span><div>${o.count}<small>/ 16</small></div><p>${o.count===16?'Full skill coverage':'Build a complete starting point'}</p></article><article class="stat-card"><span>FOCUSED PRACTICE ${icon('clock',16)}</span><div>${minutes}<small>min</small></div><p>${rows.length} completed ${rows.length===1?'drill':'drills'} in this profile</p></article><article class="stat-card"><span>TODAY’S SESSIONS ${icon('bolt',16)}</span><div>${today}<small>drills</small></div><p>${today?'Good work. Make the next rep deliberate.':'A fresh start. Make it count.'}</p></article></div>`;}
 function overview(){const rec=C.recommendation(state),o=C.overall(state),rows=C.records(state);const follow=C.priorities(state).slice(0,3).map(x=>x.skill);return top('Make every session count.','A clearer picture of your game. A more purposeful way to practice.',`<span class="context-pill">${icon('focus',15)} ${methodName()}</span>`)+`
 <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-square"></span> BUILT AROUND YOUR GAPS</div><h2>Less guesswork.<br>More <em>good rounds.</em></h2><p>Find your starting point. Train what holds you back. Bring better habits into your next match.</p><div class="hero-actions">${button(o.count?'Train my weak points '+icon('arrow',18):'Find my starting point '+icon('arrow',18),'data-action="adaptive"')}${button('Explore drills','data-page="training"','text')}</div><div class="hero-foot"><span>01 <i>ASSESS</i></span><b>→</b><span>02 <i>ADAPT</i></span><b>→</b><span>03 <i>APPLY</i></span></div></div><div class="hero-art"><img src="hero.svg" alt="Illustrated tactical shooting range with two head targets and cover"><span class="scene-label"><i></i> THE PRACTICE RANGE</span><div class="scene-note"><span>PRECISION OVER PANIC</span><b>One adjustment.<br>A better opening.</b></div><div class="scene-coordinates">S-04 / CONTROLLED ENVIRONMENT</div></div></section>
 ${stats()}
 <div class="dashboard-grid"><section class="panel next-session"><div class="section-title"><div><div class="eyebrow">YOUR NEXT MOVE</div><h2>${o.count?'Your focus queue':'Build your baseline'}</h2></div><span class="tag">ADAPTIVE</span></div><p class="muted">${o.count<16?'Unmeasured skills come first. Then we prioritize lower proficiency, limited evidence, and stale results.':'Your next focus is recalculated from proficiency, evidence, and time since practice.'}</p><div class="queue-list">${follow.map((s,i)=>{const v=C.summarize(state,s.id);return `<button class="queue-row" data-drill="${s.id}"><span class="step-number">0${i+1}</span><span class="queue-icon">${icon(s.icon)}</span><span><b>${s.name}</b><small>${v?`Level ${v.level} · ${v.value}/100 proficiency`:'Not measured yet · level 3 benchmark'}</small></span><span class="queue-arrow">↗</span></button>`;}).join('')}</div><div class="panel-foot"><span>${icon('clock',16)} ${o.count<16?'Start with one drill. Continue when ready.':'Short, focused sessions. No endless grind.'}</span>${button('Start session '+icon('arrow',16),'data-action="adaptive"','secondary')}</div></section>
 <section class="panel skill-profile"><div class="section-title"><div><div class="eyebrow">THE BIG PICTURE</div><h2>Your skill profile</h2></div><button class="text-link" data-page="progress">Details ↗</button></div>${radar()}<div class="radar-key"><span><i class="accent-dot"></i> Current proficiency</span><span>${o.count}/16 measured</span></div></section></div>
 <div class="section-title spaced"><div><div class="eyebrow">FROM PRACTICE TO PLAY</div><h2>One skill is only the beginning.</h2></div><button class="text-link" data-page="scenarios">All round scenarios ↗</button></div><div class="scenario-grid">${TC.scenarios.map(s=>scenarioCard(s)).join('')}</div>
 <section class="panel recent"><div class="section-title"><h2>Recent practice</h2><button class="text-link" data-page="progress">View history ↗</button></div>${rows.length?historyTable(rows.slice(-4).reverse()):`<div class="empty-inline"><span class="empty-icon">${icon('chart',26)}</span><div><b>Your first result starts the story.</b><p>Complete a drill to see your baseline, accuracy, and next adjustment here.</p></div>${button('Try a drill','data-page="training"','secondary')}</div>`}</section>`;}
 function radar(){const groups=['Aim','Mechanics','Tactics','Teamplay'],cx=160,cy=139,r=96;const points=(ratio)=>[[cx,cy-r*ratio],[cx+r*ratio,cy],[cx,cy+r*ratio],[cx-r*ratio,cy]].map(p=>p.join(',')).join(' ');const vals=groups.map(g=>{const a=C.skills.filter(s=>s.group===g).map(s=>C.summarize(state,s.id)).filter(Boolean);return a.length?a.reduce((s,x)=>s+x.value,0)/a.length:null;});const pp=vals.map((v,i)=>{const a=(i*Math.PI/2)-Math.PI/2;return [cx+Math.cos(a)*r*(v||0)/100,cy+Math.sin(a)*r*(v||0)/100].join(',');}).join(' ');return `<svg class="radar" viewBox="0 0 320 280" role="img" aria-label="Skill profile. ${groups.map((g,i)=>g+': '+(vals[i]===null?'unmeasured':Math.round(vals[i]))).join(', ')}">${[.25,.5,.75,1].map(v=>`<polygon points="${points(v)}" class="radar-grid"/>`).join('')}<path d="M160 43v192M64 139h192" class="radar-grid"/>${vals.some(x=>x!==null)?`<polygon points="${pp}" class="radar-data"/>`:`<circle cx="160" cy="139" r="6" fill="var(--accent)"/><text x="160" y="169" text-anchor="middle" class="radar-empty">Awaiting your first result</text>`}<text x="160" y="20" text-anchor="middle">AIM</text><text x="306" y="142" text-anchor="end">MECHANICS</text><text x="160" y="263" text-anchor="middle">TACTICS</text><text x="13" y="142">TEAMPLAY</text></svg>`;}
 function skillCard(s){const v=C.summarize(state,s.id);return `<article class="drill-card"><div class="drill-card-top"><span class="skill-icon">${icon(s.icon,23)}</span><span class="tag">${s.type==='decision'?'TACTICAL':s.type==='track'?'TRACKING':s.type==='move'?'MOVEMENT':'AIM'}</span></div><span class="eyebrow">${s.group.toUpperCase()}</span><h3>${s.name}</h3><p>${s.summary}</p><div class="skill-meter"><span style="width:${v?v.value:0}%"></span></div><div class="drill-card-meta"><span>${v?`${v.value}/100 · ${v.count} ${v.count===1?'session':'sessions'}`:'Unmeasured · establish baseline'}</span><b>${v?'L'+v.level:'L3'}</b></div><button class="button secondary full" data-drill="${s.id}">${v?'Continue training':'Open drill'}${icon('arrow',16)}</button></article>`;}
 function training(){const list=C.skills.filter(s=>(filter==='All'||s.group===filter)&&(s.name+' '+s.summary).toLowerCase().includes(search.toLowerCase()));return top('Train with intent.','Isolate the technique. Make a deliberate adjustment. Test it again.',button('Train in game','data-action="native-practice"','secondary')+button('Explore 3D map','data-action="explore-map"','secondary')+button('Adaptive session '+icon('arrow',17),'data-action="adaptive"'))+`<div class="info-strip">${icon('radar',20)}<p><b>16 distinct skills. One evolving plan.</b> Each first attempt sets a level 3 baseline. Adaptive runs adjust from level 1–8. Repeat a fixed benchmark to compare like for like.</p><button class="text-link" data-action="method">How scoring works ↗</button></div><div class="lab-toolbar"><div class="tabs" aria-label="Filter skills">${['All','Aim','Mechanics','Tactics','Teamplay'].map(g=>`<button data-filter="${g}" class="${filter===g?'selected':''}" aria-pressed="${filter===g}">${g}</button>`).join('')}</div><label class="search-label"><span>Search drills</span><input id="drill-search" type="search" placeholder="Find a technique…" value="${esc(search)}"></label></div><div class="drill-grid">${list.length?list.map(skillCard).join(''):'<div class="panel empty-state"><h2>No drills match that search.</h2><p>Try “aim,” “utility,” or clear the filter.</p><button class="button secondary" data-action="clear-search">Show all drills</button></div>'}</div><div class="info-strip subtle">${icon('focus',18)}<p>${modeName()} · ${methodName()}. Browser drills rehearse transferable components. Recoil patterns, map lineups, movement physics, and live teamwork need in-game practice.</p></div>`;}
 function scenarioCard(s){return `<article class="scenario-card ${s.color}"><div class="scenario-art">${tacticalMap(s.id==='retake'?'post':s.id==='entry'?'trade':'rotate',true)}<span class="scenario-number">0${TC.scenarios.indexOf(s)+1}</span><span class="scenario-art-tag">BRANCHING ROUND</span></div><div class="scenario-body"><span class="eyebrow">${s.tag}</span><h3>${s.name}</h3><p>${s.description}</p><div class="scenario-tags">${s.skills.slice(0,3).map(id=>`<span>${skillBy(id).name}</span>`).join('')}<span>+${s.skills.length-3}</span></div><button class="text-link" data-scenario="${s.id}">Enter scenario ${icon('arrow',17)}</button></div></article>`;}
 function scenarioList(){return top('Think beyond the duel.','Your choices change the round. Apply several skills under the same constraints.')+`<div class="scenario-intro"><span class="scenario-intro-icon">${icon('branch',32)}</span><div><h2>Every decision leaves a different angle.</h2><p>Read the situation, make your call, then play the consequence. Combined rounds include a live aim stage when your path creates an opening.</p></div><span class="tag">3 ROUND LABS</span></div><div class="scenario-grid">${TC.scenarios.map(s=>scenarioCard(s)).join('')}</div><div class="info-strip">${icon('chat',20)}<p>These are generic tactical situations, not replicas of a live map. Each response is evaluated against the information and assumptions explicitly given.</p></div>`;}
 function tacticalMap(type,small=false){const post=type==='post',trade=type==='trade',rotate=type==='rotate';return `<svg class="tactical-map" viewBox="0 0 460 270" role="img" aria-label="${post?'Objective and retake lanes':trade?'Entry and supporting teammate':rotate?'Two sites linked by mid':'Crossing lane and defender sight line'}. Blue circles are teammates; orange diamonds are known threats; dashed lines show possible routes."><defs><pattern id="mapgrid-${type}-${small}" width="23" height="23" patternUnits="userSpaceOnUse"><path d="M23 0H0v23" stroke="currentColor" opacity=".08" fill="none"/></pattern></defs><rect width="460" height="270" fill="url(#mapgrid-${type}-${small})"/><g fill="var(--map-wall)" stroke="var(--map-line)" stroke-width="1.5"><path d="M38 35h115v67H95v105H38zM193 35h114v47h-67v90h67v55H193zM347 35h75v192h-75v-57h30V93h-30z"/></g><g stroke="#7d9fbc" stroke-dasharray="5 6" stroke-width="2" fill="none"><path d="M72 234h93V128h170V63"/><path d="M280 240h48V130"/></g><path d="M339 115 255 158l84 37z" fill="#ee956d" opacity=".12"/><path d="M340 115 255 158" stroke="#ed9c70" opacity=".45"/><circle cx="166" cy="221" r="9" fill="#9fbfd9" stroke="#172d40" stroke-width="3"/><circle cx="278" cy="238" r="9" fill="#9fbfd9" stroke="#172d40" stroke-width="3"/><path d="m335 116 9 9-9 9-9-9z" fill="#f19a72"/>${post?'<circle cx="304" cy="113" r="16" fill="none" stroke="#d5cb8f" stroke-dasharray="3 3"/><text x="304" y="117" text-anchor="middle" fill="#dfd6a1" font-family="monospace" font-size="11">OBJ</text>':''}${rotate?'<text x="112" y="68" fill="#b1c4b5" font-size="21" font-family="monospace">A</text><text x="382" y="65" fill="#b1c4b5" font-size="21" font-family="monospace">B</text><text x="251" y="121" fill="#b1c4b5" font-size="10" font-family="monospace">MID</text>':''}${trade?'<path d="m166 201 0-42h80" fill="none" stroke="#a8d9b8" stroke-width="2"/><text x="76" y="251" fill="#a7bdc7" font-family="monospace" font-size="10">ENTRY + SUPPORT</text>':''}${type==='cross'?'<ellipse cx="285" cy="143" rx="24" ry="40" fill="#b4c5b7" fill-opacity=".25" stroke="#b4c5b7" stroke-dasharray="3 4"/><text x="250" y="203" fill="#bcc7be" font-size="10" font-family="monospace">BLOCK SIGHT LINE</text>':''}<g fill="#8c9c9d" font-family="monospace" font-size="8"><text x="20" y="21">TACTICAL SCHEMATIC / NOT TO SCALE</text></g></svg>`;}
 function historyTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Drill</th><th>Protocol</th><th>Proficiency</th><th>Quality</th><th>When</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${skillBy(r.skill)?.name||'Drill'}</b></td><td><span class="pill">${r.protocol==='benchmark'?'Benchmark L3':r.protocol==='scenario'?'Combined round':'Adaptive L'+r.level}</span></td><td>${r.score}<small>/100</small></td><td>${Math.round(r.quality)}%</td><td>${fmtDate(r.at)}</td></tr>`).join('')}</tbody></table></div>`;}
 function trend(rows){if(!rows.length)return `<div class="chart-empty"><div class="ghost-chart"><span></span><span></span><span></span><span></span><span></span></div><b>Your progress starts with a measurement.</b><p>Complete a drill, then return to see every session.</p>${button('Open training lab','data-page="training"','secondary')}</div>`;const data=rows.slice(-30),w=760,h=210,pad=32,px=i=>pad+(w-2*pad)*(data.length===1?.5:i/(data.length-1)),py=v=>h-pad-(h-2*pad)*v/100,pts=data.map((v,i)=>`${px(i)},${py(v.score)}`).join(' ');return `<svg class="trend-chart" viewBox="0 0 ${w} ${h+23}" role="img" aria-label="Session proficiency scores from ${data.map(x=>x.score).join(', ')} out of 100">${[0,25,50,75,100].map(y=>`<path d="M32 ${py(y)}h696" class="chart-grid"/><text x="3" y="${py(y)+4}">${y}</text>`).join('')}<polyline points="${pts}" class="chart-line"/>${data.map((v,i)=>`<circle class="chart-point" cx="${px(i)}" cy="${py(v.score)}" r="4" tabindex="0"><title>${skillBy(v.skill).name}: ${v.score}/100. Quality ${Math.round(v.quality)}%, L${v.level}, ${v.protocol}. ${fmtDate(v.at)}</title></circle>`).join('')}<text x="32" y="222">${fmtDate(data[0].at)}</text><text x="728" y="222" text-anchor="end">${fmtDate(data.at(-1).at)}</text></svg><p class="small muted">${data.length===1?'One result. More sessions reveal a trend.':'Hover or focus a point for the result.'} Difficulty-weighted trainer score; a change is not proof of a match-rank change.</p>`;}
 function progress(){const rows=C.records(state),shown=rows.filter(x=>chartSkill==='all'||x.skill===chartSkill),bench=rows.filter(x=>x.protocol==='benchmark'),o=C.overall(state);return top('See the work add up.','Starting points, recent performance, and the evidence behind every number.',button(icon('download',17)+' Export backup','data-action="export"','secondary'))+stats()+`<div class="progress-grid"><section class="panel"><div class="section-title"><div><div class="eyebrow">SESSION HISTORY</div><h2>Your training trajectory</h2></div><label class="sr-only" for="chart-skill">Choose chart skill</label><select id="chart-skill"><option value="all">All measured skills</option>${C.skills.map(s=>`<option value="${s.id}" ${chartSkill===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div>${trend(shown)}<div class="chart-legend"><span><i class="accent-dot"></i> Proficiency / 100</span><span>${modeName()} · ${methodName()} · ${bench.length} benchmarks</span></div></section><section class="panel rank-panel"><span class="eyebrow">GAME LEVEL · EVIDENCE FIRST</span><div class="rank-emblem">${icon('hex',42)}</div><h2>${esc(state.settings.rank[state.settings.game]||'Rank not recorded')}</h2><p class="small">${state.settings.rank[state.settings.game]?'Self-reported game rank · not verified':'Add your current in-game rank in Customize.'}</p><div class="rank-status"><i></i> Rank equivalence unavailable</div><p>Browser scores do not establish a competitive rank. A legitimate estimate needs a validated, rank-linked benchmark dataset for this exact protocol.</p><button class="text-link" data-action="method">See calculation & limits ↗</button></section></div>
 <section class="panel"><div class="section-title"><div><div class="eyebrow">SKILL BY SKILL</div><h2>Where you started. Where you stand.</h2></div><span class="tag">${o.count}/16 MEASURED</span></div><div class="table-scroll"><table class="skill-table"><thead><tr><th>Technique</th><th>First score</th><th>Recent score</th><th>Change</th><th>Evidence</th><th>Repeat test</th></tr></thead><tbody>${C.skills.map(s=>{const v=C.summarize(state,s.id);return `<tr><td><span class="table-skill">${icon(s.icon,17)}${s.name}</span></td><td>${v?v.baseline:'—'}</td><td>${v?v.value:'—'}</td><td><span class="${v&&v.delta>0?'positive':v&&v.delta<0?'negative':''}">${v?(v.delta>0?'+':'')+v.delta:'—'}</span></td><td>${v?`${v.count} ${v.count<3?'· provisional':'· repeated'}`:'Unmeasured'}</td><td><button class="text-link" data-benchmark="${s.id}">Benchmark ↗</button></td></tr>`;}).join('')}</tbody></table></div><p class="small muted">Recent = weighted mean of the last five scores. First and recent may have different difficulties. For a controlled comparison, repeat level 3 benchmarks with the same input and layout.</p></section>
 <section class="panel spaced-panel"><div class="section-title"><div><div class="eyebrow">CONTROLLED COMPARISONS</div><h2>Fixed level 3 benchmarks</h2></div><span class="tag">SAME PROTOCOL</span></div>${benchmarkTable(bench)}</section>
 <section class="panel spaced-panel"><div class="section-title"><h2>In-game transfer journal</h2>${button(icon('plus',16)+' Log a match','data-action="log-match"','secondary')}</div><p class="muted small">Keep real match outcomes alongside practice. Entries are self-reported. This journal does not verify skill transfer or infer your rank.</p>${state.matches.filter(x=>x.game===state.settings.game).length?`<div class="match-list">${state.matches.filter(x=>x.game===state.settings.game).slice(-6).reverse().map(x=>`<div><span>${fmtDate(x.at)}</span><b class="${x.result==='win'?'positive':''}">${x.result.toUpperCase()}</b><span>${x.rating} ${state.settings.game==='cs2'?'CS Rating':'RR (current rank)'}</span>${x.note?`<p>${esc(x.note)}</p>`:''}</div>`).join('')}</div>`:'<div class="empty-inline"><span class="empty-icon">'+icon('chat',24)+'</span><div><b>No matches logged.</b><p>After a match, record the outcome and one habit you tested.</p></div></div>'}</section>
 <section class="panel recent"><div class="section-title"><h2>All recent sessions</h2><span class="muted small">Latest 30 in this profile</span></div>${rows.length?historyTable(rows.slice(-30).reverse()):'<p class="muted">No completed sessions yet. Your data starts empty.</p>'}</section>${legacyHistory()}`;}
 function legacyHistory(){const legacy=state.sessions.filter(x=>([C.context(state),C.context(state)+':world3d1'].includes(x.context)||x.context.startsWith(C.context(state)+':world3d2:'))&&skillBy(x.skill)?.type!=='decision');return legacy.length?`<details class="legacy-results"><summary>Prior range results · ${legacy.length} sessions</summary><p>These results are retained as an archive. Weapon-specific drills establish fresh baselines because firing, recoil and damage behavior changed.</p>${historyTable(legacy.slice(-30).reverse())}</details>`:'';}
 function benchmarkTable(rows){const groups=C.skills.map(s=>({s,r:rows.filter(x=>x.skill===s.id)})).filter(x=>x.r.length);if(!groups.length)return '<div class="empty-inline"><span class="empty-icon">'+icon('focus',26)+'</span><div><b>A stable reference point.</b><p>Run a benchmark from the table above. Every repeat uses level 3 and a 30-second range or six decisions.</p></div></div>';return `<div class="table-scroll"><table><thead><tr><th>Skill</th><th>First quality</th><th>Latest quality</th><th>Change</th><th>Tests</th></tr></thead><tbody>${groups.map(({s,r})=>`<tr><td>${s.name}</td><td>${Math.round(r[0].quality)}%</td><td>${Math.round(r.at(-1).quality)}%</td><td>${Math.round(r.at(-1).quality-r[0].quality)} pp</td><td>${r.length}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Compare on the same device, orientation, viewport, and control setup. Range layout is normalized, but physical target size and hardware still affect results.</p>`;}
 function settings(){const s=state.settings;return top('Make the lab yours.','A familiar crosshair. Comfortable controls. A setup you can keep consistent.')+`<div class="settings-grid"><section class="panel"><div class="section-title"><h2>Crosshair studio</h2><span class="tag">LIVE PREVIEW</span></div><div class="cross-preview"><span class="preview-grid"></span><div id="cross-preview" aria-label="Crosshair preview"></div><small>YOUR POINT OF FOCUS</small></div><div class="form-grid"><label>Shape<select data-setting="crossStyle">${['cross','dot','circle'].map(v=>`<option value="${v}" ${s.crossStyle===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Color<input type="color" data-setting="crosshair" value="${s.crosshair}"></label><label>Size <output id="crossSize-output">${s.crossSize}</output><input type="range" min="4" max="28" value="${s.crossSize}" data-setting="crossSize"></label><label>Gap <output id="crossGap-output">${s.crossGap}</output><input type="range" min="0" max="12" value="${s.crossGap}" data-setting="crossGap"></label><label>Stroke <output id="crossWidth-output">${s.crossWidth}</output><input type="range" min="1" max="5" value="${s.crossWidth}" data-setting="crossWidth"></label></div></section>
 <section class="panel"><h2>Controls & training</h2><div class="form-stack"><label>Input profile<select data-setting="input"><option value="auto" ${s.input==='auto'?'selected':''}>Auto detect (${modeName()})</option><option value="mouse" ${s.input==='mouse'?'selected':''}>Mouse & keyboard</option><option value="touch" ${s.input==='touch'?'selected':''}>Touch</option></select><small>Touch scores are separate; these games’ desktop ranks do not transfer to touch.</small></label><label>3D camera controls<select data-setting="interaction"><option value="direct" ${s.interaction==='direct'?'selected':''}>FPS camera · capture mouse when available</option><option value="look" ${s.interaction==='look'?'selected':''}>Drag camera · drag to look, click / Fire to shoot</option></select><small>The crosshair stays centered. Both modes rotate a real 3D camera; touch always uses drag look and a movement stick.</small></label><label>Camera sensitivity <output id="sensitivity-output">${s.sensitivity}</output><input type="range" data-setting="sensitivity" min="0.2" max="3" step="0.1" value="${s.sensitivity}"></label><label>Vertical field of view <output id="fov-output">${s.fov||64}</output><input type="range" data-setting="fov" min="50" max="85" step="1" value="${s.fov||64}"><small>Keep this fixed for repeat benchmarks. Wider views change target angular size.</small></label><label>Practice weapon<select id="settings-weapon">${WeaponData.forGame(s.game).map(w=>`<option value="${w.id}" ${currentWeapon().id===w.id?'selected':''}>${esc(w.name)} · ${w.category}</option>`).join('')}</select><small>Each weapon has its own mechanical baselines. Explore supports live switching.</small></label><label>Adaptive range duration<select data-setting="duration">${[20,30,45,60].map(n=>`<option value="${n}" ${s.duration===n?'selected':''}>${n} seconds</option>`).join('')}</select><small>Benchmarks always use 30 seconds. Decision drills always use six trials.</small></label></div></section>
 <section class="panel appearance-panel"><h2>Appearance studio</h2><p class="small muted">A light workspace or a dark room. Keep your controls familiar.</p><div class="appearance-presets">${[['light','Light'],['dark','Dark']].map(([v,label])=>`<button data-theme="${v}" class="${s.theme===v?'selected':''}" aria-pressed="${s.theme===v}">${label}</button>`).join('')}</div><div class="palette-presets">${[['#f17a59','Coral'],['#df719e','Rose'],['#29a99c','Jade'],['#9277dd','Lilac']].map(([c,label])=>`<button data-accent="${c}" style="--swatch:${c}" aria-label="${label} accent"><i></i>${label}</button>`).join('')}</div><div class="form-stack"><label>Theme<select data-setting="theme"><option value="dark" ${s.theme==='dark'?'selected':''}>Graphite / dark</option><option value="light" ${s.theme==='light'?'selected':''}>Chalk / light</option></select></label><label>Accent color<input type="color" data-setting="accent" value="${s.accent}"></label><label>Layout density<select data-setting="density"><option value="comfortable" ${s.density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${s.density==='compact'?'selected':''}>Compact</option></select></label><label>Corner style<select data-setting="corners"><option value="soft" ${s.corners==='soft'?'selected':''}>Soft</option><option value="square" ${s.corners==='square'?'selected':''}>Square / Metro</option></select></label><label>HUD scale<input type="range" data-setting="hudScale" min="0.8" max="1.3" step="0.05" value="${s.hudScale}"></label><label>Weapon motion<input type="range" data-setting="weaponMotion" min="0" max="1" step="0.1" value="${s.weaponMotion}"><small>Reduce visual sway while keeping shot behavior consistent.</small></label><label class="toggle-row"><span><b>Weapon & hit audio</b><small>Synthesized gunfire and hit confirmation.</small></span><input type="checkbox" data-setting="sound" ${s.sound?'checked':''}></label><label class="toggle-row"><span><b>Reduce decorative motion</b><small>Also respects your device’s reduced motion setting.</small></span><input type="checkbox" data-setting="reduced" ${s.reduced?'checked':''}></label></div></section>
 <section class="panel"><h2>Game context & data</h2><div class="form-stack"><label>Your ${gameName()} rank${s.game==='valorant'?`<select id="rank-input"><option value="">Not recorded</option>${['Iron','Bronze','Silver','Gold','Platinum','Diamond','Ascendant','Immortal'].flatMap(rank=>[1,2,3].map(n=>rank+' '+n)).concat(['Radiant']).map(rank=>`<option ${s.rank.valorant===rank?'selected':''}>${rank}</option>`).join('')}</select>`:`<input id="rank-input" maxlength="50" placeholder="e.g. Premier 12,500 or map rank" value="${esc(s.rank.cs2)}">`}<small>Self-reported context. Stratum does not connect to your game account.</small></label><div class="data-actions">${button(icon('download',16)+' Export backup','data-action="export"','secondary')}<label class="button secondary import-label">Import backup<input type="file" id="import-file" accept="application/json,.json"></label></div><p class="small muted">Results stay in this browser on this device. Export before clearing browser data or switching devices. There is no account sync.</p><button class="text-link danger" data-action="reset">Reset this device’s training data</button></div></section></div>`;}
 function wireInputs(){$('#settings-weapon')?.addEventListener('change',e=>chooseWeapon(e.target.value));const q=$('#drill-search');if(q)q.addEventListener('input',e=>{search=e.target.value;const pos=e.target.selectionStart;$('#main').innerHTML=training();wireInputs();const next=$('#drill-search');next.focus();try{next.setSelectionRange(pos,pos);}catch{}});$('#chart-skill')?.addEventListener('change',e=>{chartSkill=e.target.value;render();});$$('[data-setting]').forEach(el=>el.addEventListener('input',()=>{const key=el.dataset.setting;state.settings[key]=el.type==='checkbox'?el.checked:el.type==='range'||key==='duration'?Number(el.value):el.value;applySettings();persist();const output=$('#'+key+'-output');if(output)output.value=el.value;drawCross();renderNav();}));$('#rank-input')?.addEventListener('change',e=>{state.settings.rank[state.settings.game]=e.target.value.trim();persist();toast('Game rank recorded as self-reported context.');});$('#import-file')?.addEventListener('change',importData);drawCross();}
 function currentWeapon(){return WeaponData.byId(state.settings.loadout?.[state.settings.game])||WeaponData.byId(WeaponData.defaults[state.settings.game]);}
 function chooseWeapon(id){const selected=WeaponData.byId(id);if(!selected||selected.game!==state.settings.game)return;if(active&&!active.explore&&active.phase!=='ready'){toast('Scored drills keep one weapon. Finish or exit this attempt, or use Explore to switch freely.');return;}if(range&&!range.switchWeapon(id)&&range.weapon.id!==id)return;state.settings.loadout[state.settings.game]=id;persist();closeModal();if(active){if(!active.explore){const measured=C.summarize(state,active.skill.id);active.level=measured?.level||3;active.protocol=measured?'adaptive':'benchmark';active.duration=measured?state.settings.duration:30;range?.destroy();range=null;renderActive();}}else render();toast(selected.name+' selected.');}
 function weaponArt(w){const supported=['classic','shorty','frenzy','ghost','sheriff','stinger','spectre','bucky','judge','bulldog','guardian','phantom','vandal','marshal','outlaw','operator','ares','odin'];const id=w.id.replace('valorant-','');return w.game==='valorant'&&supported.includes(id)?`<img src="assets/catalog/valorant/${id}.png" alt="" loading="lazy" class="weapon-art">`:'';}
 function armory(){const w=currentWeapon(),locked=active&&!active.explore&&active.phase!=='ready';modal(`<h2>Choose your weapon.</h2><p>${gameName()} · ${WeaponData.forGame(state.settings.game).length} firearm profiles. ${locked?'This attempt keeps its starting weapon. Use Explore for live switching.':'Choose a firearm to equip it. In Explore, 1/2 switch primary/sidearm and Q returns to the previous weapon.'}</p><div class="weapon-current"><b>${esc(w.name)}</b><span>${w.mag} rounds · ${w.rate.toFixed(2)} rounds/s · ${w.reload.toFixed(2)}s reload</span></div><div class="armory-grid">${WeaponData.forGame(state.settings.game).map(g=>`<button data-weapon="${g.id}" class="${w.id===g.id?'selected':''}" ${locked?'disabled':''}>${weaponArt(g)}<b>${esc(g.name)}</b><small>${g.category} · ${g.mag} rounds · ${g.fireMode}${g.id==='valorant-warden'?' · API listing':''}</small></button>`).join('')}</div><p class="small muted armory-note">Rates, capacities and damage are sourced. Recoil, movement and animation timing remain training approximations. Cover blocks shots; wall penetration is not simulated. Detailed models represent weapon families; they are not the official game meshes.</p><button class="text-link" data-action="asset-credits">Asset credits & weapon sources ↗</button>`);}
 async function assetCredits(){let credits;try{credits=await fetch('assets/credits.json').then(r=>r.json());}catch{}const sources=[...new Map((credits?.models||[]).flatMap(m=>m.sources||[]).map(a=>[a.url,a])).values()];modal(`<h2>Assets & sources</h2><p>Independent practice environment. Runtime posing, scaling and procedural weapon animations by Stratum.</p><ul class="asset-credit-list">${sources.map(a=>`<li><a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.title)}</a> — ${esc(a.author)} · <a href="${esc(a.licenseUrl)}" target="_blank" rel="noopener">${esc(a.license)}</a></li>`).join('')}</ul><p>Surface textures: ambientCG / Lennart Demes; eye-candy.xyz / Poly Haven; Amal Kumar / Poly Haven. CC0.</p><p><a href="assets/credits.json" target="_blank" rel="noopener">Complete attribution, modifications and sources ↗</a> · <a href="assets/vendor-licenses.txt" target="_blank" rel="noopener">Graphics library licenses ↗</a></p><p><a href="https://valorant-api.com/" target="_blank" rel="noopener">VALORANT weapon data ↗</a> · <a href="https://github.com/SteamTracking/GameTracking-CS2" target="_blank" rel="noopener">CS2 tracked game data ↗</a></p><p class="small muted">Models represent weapon families, not official Riot or Valve meshes. Weapon values are a dated snapshot. Accuracy, recoil and engine integration are approximations. Original map; no official game map is reproduced.</p>`);}
 function drawCross(){const el=$('#cross-preview');if(!el)return;const s=state.settings,n=s.crossSize,g=s.crossGap,t=s.crossWidth;el.innerHTML=s.crossStyle==='cross'?`<i style="left:calc(50% - ${g+n}px);top:calc(50% - ${t/2}px);width:${n}px;height:${t}px"></i><i style="left:calc(50% + ${g}px);top:calc(50% - ${t/2}px);width:${n}px;height:${t}px"></i><i style="left:calc(50% - ${t/2}px);top:calc(50% - ${g+n}px);height:${n}px;width:${t}px"></i><i style="left:calc(50% - ${t/2}px);top:calc(50% + ${g}px);height:${n}px;width:${t}px"></i>`:`<i style="left:50%;top:50%;transform:translate(-50%,-50%);width:${s.crossStyle==='dot'?t*2:n*2}px;height:${s.crossStyle==='dot'?t*2:n*2}px;border-radius:50%;${s.crossStyle==='circle'?`border:${t}px solid ${s.crosshair};background:transparent;`:''}"></i>`;el.style.setProperty('--cross-color',s.crosshair);}
 function modal(html){if(active?.phase==='running')pauseSession();lastFocus=document.activeElement;$('#modal-body').innerHTML=`<button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>`+html;$('#modal').showModal();}
 function closeModal(){if($('#modal').open)$('#modal').close();lastFocus?.focus();}
 function instructions(s){const touch=C.inputMode(state.settings)==='touch';if(s.type==='decision')return 'Read the full situation. Select the best action before the timer ends. Review the explanation, then continue.';const controls=touch?'Left stick moves. Drag the world to look. Use Fire, Jump, and Crouch.':'WASD moves; mouse capture or drag rotates your view. Hold click or F to fire. Right click aims or uses alternate fire. R reloads, B opens the armory, 1/2 switch slots, Space jumps.';const focus=s.id==='tracking'?'Keep the centered crosshair on the strafing head. No firing needed.':s.id==='switching'?'Clear numbered heads in order. Walls and bodies block shots.':s.id==='peek'?'Navigate around solid cover, reveal the target, settle, and fire.':s.id==='stopfire'?'Move to a new position, stop, then land the head shot.':s.id==='burst'?'Land head shots with deliberate taps and a reset between shots.':'Aim the centered crosshair at a head, then fire. Targets occupy real positions in the map.';return controls+' '+focus;}

 function drillModal(id,benchmark=false){const s=skillBy(id),v=C.summarize(state,id),level=benchmark||!v?3:v.level;modal(`<div class="modal-icon">${icon(s.icon,30)}</div><span class="eyebrow">${s.group.toUpperCase()} / ${benchmark||!v?'FIXED BENCHMARK':'ADAPTIVE DRILL'}</span><h2>${s.name}</h2><p>${s.summary}</p><div class="brief-meta"><span>LEVEL <b>${level} / 8</b></span><span>${s.type==='decision'?'6 DECISIONS':`${benchmark||!v?30:state.settings.duration} SECONDS`}</span><span>${modeName().toUpperCase()}</span></div><h3>The technique</h3><p>${s.transfer}</p><h3>How to play</h3><p>${instructions(s)}</p><details class="follow-through"><summary>Apply this in ${gameName()}</summary><ol>${TC.followThrough(s.id,state.settings.game).map(x=>`<li>${x}</li>`).join('')}</ol></details><div class="info-strip subtle"><p><b>Progression:</b> ${s.variable} With enough trials, quality ≥85% raises the next level; below 50% lowers it. Small samples and incomplete sessions keep the same level.</p></div>${button('Start '+(benchmark||!v?'benchmark':'drill')+' '+icon('arrow',17),`data-start="${s.id}" data-fixed="${benchmark||!v}"`,'primary full')}`);}
 function beginDrill(id,fixed=false){range?.destroy();range=null;clearInterval(decisionTimer);closeModal();const s=skillBy(id),v=C.summarize(state,id);active={skill:s,level:fixed?3:v?.level||3,protocol:fixed?'benchmark':'adaptive',phase:'ready',duration:fixed?30:state.settings.duration,startedAt:0,decision:0,success:0,trials:0,answers:[],questions:s.type==='decision'?TC.questions(s.id,state.settings.game,fixed?3:v?.level||3):null};page='training';renderNav();renderActive();window.scrollTo({top:0,behavior:'instant'});}
 function startAdaptive(){queue=C.skills.filter(s=>!C.summarize(state,s.id)).map(s=>s.id);if(!queue.length){queue=C.priorities(state).slice(0,3).map(x=>x.skill.id);}const first=queue.shift();beginDrill(first,!C.summarize(state,first));}
 function renderActive(){const a=active,s=a.skill;$('#main').innerHTML=top(a.explore?(state.settings.game==='valorant'?'The Pavilion.':'Explore Courtyard 04.'):s.name+(a.combined?.length?' + '+skillBy(a.combined[0]).name:''),`${a.explore?gameName()+' · Untimed map walk':a.protocol==='benchmark'?'Fixed 3D benchmark':'Adaptive practice'} · Level ${a.level} / 8 · ${modeName()} · ${methodName()}`,button('Exit session','data-action="exit-session"','secondary'),a.explore)+`<div class="training-layout ${s.type==='decision'?'':'world-training'}"><section class="range-panel"><div class="range-toolbar"><span><i class="status-dot"></i> <b id="run-state">${a.phase==='ready'?'READY':'LIVE'}</b></span><span id="run-progress">${a.explore?'UNTIMED':s.type==='decision'?'6 decisions':fmtTime(a.duration)}</span><span id="run-score">—</span></div><div id="arena" class="arena ${s.type==='decision'?'decision-arena':''}"></div><div class="range-bottom"><span>${icon('focus',16)} ${a.explore?gameName()+' · Untimed map walk':a.protocol==='benchmark'?'Fixed L3 reference':'Adaptive L'+a.level} · ${state.settings.game.toUpperCase()}</span><span class="range-actions">${s.type!=='decision'?'<button class="text-link" data-action="armory">Armory [B]</button>':''}${s.type!=='decision'?'<button class="text-link" data-action="expand-range">Expand view</button>':''}<button class="text-link" data-action="pause-session">Pause / Esc</button></span></div></section><aside class="coach-panel panel"><span class="eyebrow">THE FOCUS</span><h2>${s.name}</h2><p>${s.transfer}</p><div class="coach-divider"></div><h3>Make it deliberate.</h3><p class="small">${instructions(s)}</p><div class="coach-divider"></div><span class="eyebrow">DIFFICULTY LEVERS</span><p class="small">${s.variable}</p><div class="coach-level">${Array.from({length:8},(_,i)=>`<span class="${i<a.level?'on':''}"></span>`).join('')}</div>${a.combined?.length?`<div class="combined-tag">COMBINED WITH ${skillBy(a.combined[0]).name.toUpperCase()}</div>`:''}<small class="muted">Level ${a.level} of 8 · no official rank mapping</small><button class="text-link" data-action="fieldwork">In-game follow-through ↗</button>${queue.length?`<div class="queued-note">${queue.length} more skills in this queue. Continue or stop after any drill.</div>`:''}</aside></div>`;if(s.type==='decision')renderDecisionReady();else renderRangeReady();}
 function renderRangeReady(){const a=active,touch=C.inputMode(state.settings)==='touch';$('#arena').classList.add('world-arena');$('#arena').dataset.game=state.settings.game;$('#arena').innerHTML=`<canvas id="range-canvas" tabindex="0" role="application" aria-label="Navigable 3D map. ${esc(instructions(a.skill))}"></canvas><canvas class="world-hud" aria-hidden="true"></canvas><div class="arena-overlay world-ready" id="range-overlay"><h2>${a.explore?'Walk the map. Learn the angles.':'Step into the drill.'}</h2><p>${a.explore?(state.settings.game==='valorant'?'An open practice pavilion, target lanes, and a dedicated tactical HUD.':'A connected 3D courtyard with two routes, solid cover, and an elevated catwalk.'):instructions(a.skill)}</p><div class="world-key-guide">${touch?'<span>LEFT STICK <b>Move</b></span><span>DRAG WORLD <b>Look</b></span><span>FIRE <b>Centered aim</b></span>':'<span>W A S D <b>Move</b></span><span>MOUSE <b>Look</b></span><span>HOLD CLICK <b>Fire</b></span><span>SPACE <b>Jump</b></span>'}</div>${button(a.explore?'Enter 3D map':'Enter 3D range','data-action="launch-range"')}<small>${state.settings.game==='valorant'?'The Pavilion':'Courtyard 04'} · Independent browser simulation · Use Train in game for native mechanics</small></div><div class="world-controls ${touch?'touch-profile':''}" id="touch-controls" hidden><button class="move-stick" id="move-stick" aria-label="Movement joystick. Drag to walk in any direction"><span class="stick-knob"></span></button><div class="world-tools"><button data-action="world-jump" aria-label="Jump">Jump</button><button data-action="world-crouch" aria-pressed="false">Crouch</button><button data-action="world-reload" aria-label="Reload weapon">Reload</button><button data-action="world-aim" aria-label="Aim down sights or alternate fire">Aim / Alt</button><button class="fire-pad" data-action="fire">FIRE</button></div></div>`;try{range=new RangeTrainer($('#range-canvas'),{...state.settings,combined:a.combined,explore:a.explore,scene:scenario?.pack.id},a.skill.id,a.level,a.duration,{finish:finishRange,update:updateRange,pause:showPause,notice:toast,armory:armory,weapon:w=>{state.settings.loadout[state.settings.game]=w.id;persist();const caption=$('.page-heading p');if(caption)caption.textContent=(a.explore?gameName()+' · Untimed map walk':a.protocol==='benchmark'?'Fixed 3D benchmark':'Adaptive practice')+' · Level '+a.level+' / 8 · '+modeName()+' · '+methodName();},error:message=>{$('#arena').innerHTML=`<div class="empty-state"><h2>3D view interrupted</h2><p>${esc(message)}</p>${button('Return to training','data-action="abandon"','secondary')}</div>`;}});}catch(e){range?.destroy();range=null;$('#arena').innerHTML=`<div class="empty-state world-error"><h2>3D range unavailable</h2><p>${esc(e.message)}</p>${button('Return to training','data-action="abandon"','secondary')}</div>`;}bindMovePads();}

 function bindMovePads(){const fire=$('.fire-pad');if(fire){fire.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();range?.pressFire(e,'pad:'+e.pointerId);fire.setPointerCapture(e.pointerId);});for(const type of ['pointerup','pointercancel','lostpointercapture'])fire.addEventListener(type,e=>type==='pointerup'?range?.releasePointer(e):range?.cancelPointer(e));}const stick=$('#move-stick');if(!stick)return;let pointer=null;const move=e=>{if(e.pointerId!==pointer||!range||range.paused)return;e.preventDefault();const box=stick.getBoundingClientRect(),x=C.clamp((e.clientX-box.left-box.width/2)/(box.width*.36),-1,1),y=C.clamp((e.clientY-box.top-box.height/2)/(box.height*.36),-1,1);range.touch={x,y};stick.querySelector('.stick-knob').style.transform=`translate(${x*24}px,${y*24}px)`;};const release=e=>{if(e.pointerId!==pointer)return;pointer=null;if(range)range.touch={x:0,y:0};stick.querySelector('.stick-knob').style.transform='';};stick.addEventListener('pointerdown',e=>{if(!range||range.paused)return;pointer=e.pointerId;stick.setPointerCapture(e.pointerId);move(e);});stick.addEventListener('pointermove',move);for(const event of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(event,release);}

 function launchRange(){if(!range)return;active.phase='running';$('#range-overlay').remove();$('#run-state').textContent=active.explore?'MAP WALK':'LIVE';$('#touch-controls').hidden=false;if(active.skill.id==='tracking')$('.fire-pad').hidden=true;range.start();if(C.inputMode(state.settings)==='mouse'&&state.settings.interaction==='direct')range.lock();}
 function openMap(){if(active||scenario)return;queue=[];active={skill:skillBy('precision'),level:3,protocol:'explore',phase:'ready',duration:Infinity,explore:true};page='training';renderNav();renderActive();window.scrollTo({top:0,behavior:'instant'});}
 function expandRange(){const panel=$('.range-panel');if(!panel)return;const on=panel.classList.toggle('is-expanded');$('[data-action="expand-range"]').textContent=on?'Exit expanded view':'Expand view';range?.resize();}

 function updateRange(result){if(!active)return;$('#run-progress').textContent=active.explore?'UNTIMED':fmtTime(Math.max(0,active.duration-result.duration));$('#run-score').textContent=active.explore?result.zone:active.skill.id==='tracking'?result.accuracy+'% on target':result.hits+' hits · '+result.accuracy+'%';}
 function renderDecisionReady(){const a=active;$('#arena').innerHTML=`<div class="decision-ready">${tacticalMap('rotate')}<div><span class="eyebrow">DECISION LAB</span><h2>Read the round.</h2><p>Six tactical situations. Each choice is scored against the stated information. Timeouts count as missed decisions.</p>${button('Begin decisions '+icon('arrow',17),'data-action="launch-decisions"')}</div></div>`;}
 function launchDecisions(){active.phase='running';active.startedAt=performance.now();showQuestion();}
 function showQuestion(){clearInterval(decisionTimer);const a=active,q=a.questions[a.decision];a.remaining=a.protocol==='benchmark'?25:Math.max(8,31-a.level*2);a.answered=false;$('#arena').innerHTML=`<div class="decision-content"><div class="decision-map">${tacticalMap(q.map||'rotate')}<div class="map-key"><span>● Your team</span><span>◆ Confirmed threat</span><span>┄ Possible route</span></div></div><div class="decision-question"><div class="eyebrow">${q.advanced?'COMBINED CONSTRAINTS · ':''}DECISION ${a.decision+1} OF 6 <span> / </span> <span id="decision-time">${a.remaining}s</span></div><h2>${q.prompt}</h2><div class="decision-options">${q.options.map((text,i)=>`<button data-answer="${i}"><span>${i+1}</span>${esc(text)}</button>`).join('')}</div><div id="answer-feedback" aria-live="polite"></div></div></div>`;$('#run-state').textContent='LIVE';$('#run-progress').textContent=`${a.decision+1} / 6`;$('#run-score').textContent=`${a.success} correct`;decisionTimer=setInterval(()=>{if(!active||a.phase!=='running'||a.answered)return;a.remaining--;const time=$('#decision-time');if(time)time.textContent=a.remaining+'s';if(a.remaining<=0)answerQuestion(-1);},1000);}
 function answerQuestion(index){const a=active;if(!a||a.answered||a.phase!=='running')return;clearInterval(decisionTimer);a.answered=true;const q=a.questions[a.decision],ok=index===q.answer;a.trials++;if(ok)a.success++;a.answers.push({ok,prompt:q.prompt,why:q.why});$$('[data-answer]').forEach((b,i)=>{b.disabled=true;if(i===q.answer)b.classList.add('correct');else if(i===index)b.classList.add('incorrect');});$('#answer-feedback').innerHTML=`<div class="answer-feedback ${ok?'correct':'incorrect'}"><b>${ok?'Good decision.':index===-1?'Time expired.':'Adjust the decision.'}</b><p>${q.why}</p>${button(a.decision===5?'See session result':'Next situation '+icon('arrow',16),'data-action="next-question"','secondary')}</div>`;$('#run-score').textContent=`${a.success} / ${a.trials} correct`;}
 function nextQuestion(){if(!active?.answered)return;active.decision++;if(active.decision>=6){const a=active;showResult({success:a.success,trials:a.trials,quality:a.success/a.trials*100,duration:(performance.now()-a.startedAt-(a.pausedMs||0))/1000,meanMs:null});}else showQuestion();}
 function showPause(){if(!active||active.phase!=='running')return;active.phase='paused';active.pausedAt=performance.now();$('#run-state').textContent='PAUSED';const el=document.createElement('div');el.className='arena-overlay pause-overlay';el.id='pause-overlay';el.innerHTML=`<span class="eyebrow">TAKE YOUR TIME</span><h2>Session paused.</h2><p>The timer is stopped. Resume when you are ready.</p>${button('Resume session','data-action="resume-session"')}`;$('#arena').append(el);}
 function pauseSession(){if(!active||active.phase!=='running')return;if(range)range.pause();else showPause();}
 function resumeSession(){if(!active||active.phase!=='paused')return;active.pausedMs=(active.pausedMs||0)+(performance.now()-(active.pausedAt||performance.now()));active.phase='running';$('#pause-overlay')?.remove();$('#run-state').textContent='LIVE';range?.resume();if(range&&C.inputMode(state.settings)==='mouse'&&state.settings.interaction==='direct')range.lock();}
 function finishRange(result){range?.destroy();range=null;showResult(result);}
 function saveSession(skill,raw,protocol,level){const row={id:crypto.randomUUID(),skill,context:C.context(state,skill),at:Date.now(),quality:Math.round(C.clamp(raw.quality,0,100)*10)/10,score:C.score(raw.quality,level),level,nextLevel:protocol==='scenario'?(C.summarize(state,skill)?.level||3):raw.trials>=(skill==='tracking'?50:skillBy(skill).type==='decision'?6:8)?C.nextLevel(level,raw.quality):level,protocol,weapon:skillBy(skill).type==='decision'?null:currentWeapon().id,engine:skillBy(skill).type==='decision'?'decisions-v1':'world3d-weapons-v3',duration:Math.max(1,raw.duration),trials:raw.trials,success:raw.success,meanMs:raw.meanMs||null,fov:state.settings.fov||64,sensitivity:state.settings.sensitivity,countTime:raw.countTime!==false,viewport:[innerWidth,innerHeight],orientation:innerWidth>innerHeight?'landscape':'portrait'};state.sessions.push(row);persist();return row;}
 function showResult(raw){clearInterval(decisionTimer);const a=active;let row=null;if(raw.trials>0)row=saveSession(a.skill.id,raw,a.protocol,a.level);a.phase='result';a.result=raw;a.row=row;if(raw.components)for(const [id,metric]of Object.entries(raw.components))if(metric.trials)saveSession(id,metric,'scenario',a.level);const interval=C.wilson(raw.success,raw.trials);$('#run-state').textContent='COMPLETE';$('#run-progress').textContent=fmtTime(raw.duration);$('#arena').innerHTML=`<div class="result-screen"><div class="eyebrow">SESSION COMPLETE / ${a.protocol.toUpperCase()}</div><div class="result-number">${row?row.score:'—'}<span>/ 100</span></div><h2>${raw.quality>=85?'A clean session. Raise the challenge.':raw.quality<50?'Slow it down. Build the technique.':'Keep the technique consistent.'}</h2><div class="result-stats"><span><b>${Math.round(raw.quality)}%</b>Quality</span><span><b>${raw.success} / ${raw.trials}</b>${a.skill.id==='tracking'?'On-target samples':'Successful trials'}</span><span><b>${raw.meanMs?raw.meanMs+' ms':'—'}</b>Mean acquisition</span></div><p class="result-explanation">${raw.trials?`${a.skill.id==='tracking'?'Tracking samples are temporally correlated; the percentage is descriptive.':`95% Wilson interval for trial success: ${interval[0]}–${interval[1]}%.`} ${raw.trials<12?'Small sample; treat this result as provisional.':''}`:'No valid trials were captured, so no score was saved.'}</p>${raw.components?`<p class="combined-result">Movement component: ${Object.values(raw.components).map(m=>Math.round(m.quality)+'% valid stop / exposure timing').join(' · ')}. Precision success also requires these conditions.</p>`:''}<div class="result-cue"><b>Your next adjustment</b><p>${a.skill.transfer}</p><details class="follow-through"><summary>Take the technique into ${gameName()}</summary><ol>${TC.followThrough(a.skill.id,state.settings.game).map(x=>`<li>${x}</li>`).join('')}</ol></details><small>Next adaptive difficulty: L${row?row.nextLevel:a.level}. A fixed benchmark always remains L3. Progression needs 8 mechanical trials, 50 tracking samples, or 6 decisions.</small></div><div class="result-actions">${button(queue.length?'Continue queue '+icon('arrow',17):'Train next focus '+icon('arrow',17),'data-action="next-focus"')}${button('View progress','data-action="finish-progress"','secondary')}${button('Repeat benchmark',`data-action="repeat-benchmark"`,'text')}</div></div>`;if(scenario?.aimActive)renderScenarioAimResult(raw,row);}
 function abandon(){range?.destroy();range=null;clearInterval(decisionTimer);active=null;queue=[];scenario=null;render();}
 function finishTo(p){range?.destroy();range=null;clearInterval(decisionTimer);active=null;queue=[];scenario=null;page=p;location.hash=p;render();}
 function startScenario(id){scenario={pack:TC.scenarios.find(s=>s.id===id),node:null,path:[],metrics:{},aimActive:false,started:performance.now()};scenario.node=scenario.pack.start;page='scenarios';renderNav();renderScenario();window.scrollTo({top:0,behavior:'instant'});}
 function renderScenario(){const sc=scenario,n=sc.pack.nodes[sc.node];if(sc.node==='end'){finishScenario();return;}$('#main').innerHTML=top(sc.pack.name,'Combined round · your decisions shape the next situation.',button('Exit round','data-action="exit-scenario"','secondary'))+`<div class="scenario-workspace"><section class="panel scenario-play"><div class="section-title"><span class="eyebrow">${skillBy(n.skill).name.toUpperCase()}</span><span class="tag">STEP ${sc.path.length+1}</span></div>${tacticalMap(n.map||'trade')}<div class="scenario-prompt"><h2>${n.title}</h2><p>${n.text}</p><div class="decision-options">${n.aim?button('Enter live aim stage '+icon('play',17),'data-action="scenario-aim"','primary'):n.options.map((o,i)=>`<button data-scenario-choice="${i}"><span>${String.fromCharCode(65+i)}</span>${esc(o.text)}</button>`).join('')}</div><div id="scenario-feedback" aria-live="polite"></div></div></section><aside class="panel branch-panel"><span class="eyebrow">YOUR ROUND, SO FAR</span><h2>A path you created.</h2><div class="branch-path">${sc.path.length?sc.path.map((p,i)=>`<div class="branch-node ${p.ok?'good':'miss'}"><span>${i+1}</span><div><b>${esc(p.title)}</b><small>${p.ok?'Sound technique':'Adjustment needed'}</small></div></div>`).join(''):'<div class="empty-path"><span>01</span><p>Your first choice opens the next branch.</p></div>'}</div><p class="small muted">A poor decision can remove the aim opportunity or create a harder recovery. Each tested skill receives a small-sample result in history. Full drills establish proficiency.</p></aside></div>`;}
 function scenarioChoice(i){const sc=scenario,n=sc.pack.nodes[sc.node];if(sc.pending)return;const choice=n.options[i];sc.pending=choice;const m=sc.metrics[n.skill]||{trials:0,success:0};m.trials++;if(choice.ok)m.success++;sc.metrics[n.skill]=m;sc.path.push({title:n.title,ok:choice.ok});$$('[data-scenario-choice]').forEach((b,j)=>{b.disabled=true;if(j===i)b.classList.add(choice.ok?'correct':'incorrect');});$('#scenario-feedback').innerHTML=`<div class="answer-feedback ${choice.ok?'correct':'incorrect'}"><b>${choice.ok?'A useful decision.':'The round changes.'}</b><p>${choice.why}</p>${button('Play the consequence '+icon('arrow',16),'data-action="scenario-next"','secondary')}</div>`;}
 function scenarioNext(){if(!scenario?.pending)return;scenario.node=scenario.pending.next;scenario.pending=null;renderScenario();}
 function scenarioAim(){const sc=scenario,n=sc.pack.nodes[sc.node];sc.aimActive=true;const v=C.summarize(state,n.skill);active={skill:skillBy(n.skill),level:v?.level||3,protocol:'scenario',duration:20,phase:'ready',combined:[n.skill==='placement'?'peek':'stopfire']};renderActive();}
 function renderScenarioAimResult(raw,row){scenario.aimActive=false;scenario.aimDuration=(scenario.aimDuration||0)+raw.duration;scenario.path.push({title:scenario.pack.nodes[scenario.node].title,ok:raw.quality>=60});scenario.node=scenario.pack.nodes[scenario.node].next;$('#arena .result-actions').innerHTML=button('Return to the round '+icon('arrow',17),'data-action="return-scenario"');}
 function finishScenario(){const sc=scenario;if(!sc.saved){const duration=Math.max(1,(performance.now()-sc.started)/1000-(sc.aimDuration||0));const entries=Object.entries(sc.metrics);for(const [id,m]of entries)saveSession(id,{...m,quality:m.success/m.trials*100,duration:Math.max(1,duration/entries.length)},'scenario',3);sc.saved=true;}$('#main').innerHTML=top('Round reviewed.','A look at the decisions that built this round.')+`<section class="panel round-review"><div class="round-review-icon">${icon('branch',42)}</div><span class="eyebrow">${sc.pack.name.toUpperCase()}</span><h2>${sc.path.filter(p=>p.ok).length} sound steps out of ${sc.path.length}.</h2><p>Each decision is evidence about the skill it tested. One round is a small sample, not a definitive level.</p><div class="review-path">${sc.path.map((p,i)=>`<div><span class="${p.ok?'positive':'negative'}">${p.ok?'✓':'·'}</span><b>${i+1}. ${esc(p.title)}</b><small>${p.ok?'Sound technique':'Revisit this technique'}</small></div>`).join('')}</div><div class="result-actions">${button('View my progress','data-action="finish-progress"')}${button('Explore more rounds','data-action="finish-scenarios"','secondary')}</div></section>`;}
 function nativePractice(){const cs=state.settings.game==='cs2';modal(`<h2>Practice in ${cs?'Counter-Strike 2':'VALORANT'}.</h2><p>Use the installed game for its actual engine, weapon animations, recoil, maps and graphics. The browser range is an independent simulation.</p>${cs?`<p>Open CS2, choose Play → Practice, then select your map. Use an offline practice session.</p><a class="button primary" href="steam://run/730">Open Counter-Strike 2</a><ol class="fieldwork-list"><li>Start with a stationary first-shot drill using your chosen weapon.</li><li>Strafe, stop, and fire at a fixed point. Observe when accuracy returns.</li><li>Use the workshop browser for an aim-training map, then repeat the same weapon and sensitivity.</li></ol>`:`<p>Open the Riot Client → VALORANT → Play → Practice → The Range. Select your weapon and enable practice bots.</p><ol class="fieldwork-list"><li>Use stationary bots to measure first-shot precision.</li><li>Enable bot strafing. Move, stop, and fire one round at a time.</li><li>Repeat with the same sensitivity and weapon. Use the game's shooting test to compare results.</li></ol><a class="text-link" href="https://playvalorant.com/" target="_blank" rel="noopener">Open official VALORANT site ↗</a>`}<p class="small muted">Launching a game does not link telemetry. Results from these steps are not automatically scored here.</p>`);}
 function method(){modal(`<span class="eyebrow">MEASURE WHAT IS REAL</span><h2>What the numbers mean.</h2><div class="method-content"><h3>Measured trainer proficiency</h3><p>Quality is successful head shots / shot attempts and missed visible exposure windows. Hidden targets do not expire behind walls; for tracking, it is the share of 100 ms samples on target; for decisions, correct choices / six trials. Stop-fire and angle clearing also require movement and a settled shot.</p><p><code>Score = quality × (0.5 + 0.5 × level / 8)</code></p><p>The score weights a harder task more strongly. It is an internal training index, not a validated psychometric measure or player percentile. Scenario decisions are small-sample evidence shown in history; full drills establish adaptive proficiency. Recent proficiency is the weighted mean of the last five scores, with weights 1 through N toward the newest.</p><h3>Baselines & adaptation</h3><p>Your first drill uses a fixed level 3 benchmark. Benchmark range runs last 30 seconds; decision benchmarks use six questions and 25 seconds per question. Adaptive quality at least 85% raises the next level; below 50% lowers it. Levels are capped at 1–8. Promotion or reduction needs at least 8 aim/movement trials, 50 tracking samples, or 6 decisions; incomplete and small-sample attempts do not change difficulty. The next queue first samples unmeasured skills, then lower scores with limited or stale evidence.</p><h3>Game levels</h3><p>No rank equivalence is calculated because this app has no validated rank-linked benchmark dataset. Assigning Gold, Immortal, or a CS Rating from these browser tasks would be invented. Your recorded rank and match journal are explicitly self-reported. Confidence, latency, device, and game sense cannot be collapsed into an honest official rank here.</p><h3>Transfer & compatibility</h3><p>The mechanical drills use a navigable 3D map with collision, elevation, and wall-tested shot rays. Movement and weapon timings are training approximations; this original map does not reproduce either game's exact maps, recoil, agents, audio, or network conditions. Complete the in-game follow-through for each technique. Touch and mouse, mouse capture and drag look, and the two games each keep separate results. Keep device, field of view, and layout consistent for benchmarks. Earlier 2D mechanical results remain in your backup; they are excluded from new 3D baselines.</p><h3>Source basis</h3><p><button class="text-link" data-action="asset-credits">View asset and weapon-data credits ↗</button></p><p><a href="https://playvalorant.com/en-us/news/announcements/beginners-guide/" target="_blank" rel="noopener">Riot: VALORANT beginner’s guide ↗</a> — movement, angles, utility, economy, and communication.</p><p><a href="https://support.riotgames.com/en-us/valorant/gameplay/valorant-competitive-mode-faq" target="_blank" rel="noopener">Riot: competitive mode FAQ ↗</a> — official competitive ranks.</p><p><a href="https://www.counter-strike.net/cs2" target="_blank" rel="noopener">Valve: Counter-Strike 2 ↗</a> — game-specific movement and shot timing context. Generic scenarios are original educational abstractions. Not affiliated with Riot Games or Valve.</p></div>`);}
 function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='stratum-training-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it to restore your training profile.');}
 async function importData(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>8e6)throw Error('Backup is too large. Maximum size is 8 MB.');const next=C.validate(JSON.parse(await f.text()));modal(`<span class="eyebrow">RESTORE BACKUP</span><h2>Replace this device’s profile?</h2><p>This backup contains ${next.sessions.length} sessions. Your existing profile has ${state.sessions.length}. Export your current data first if you want to keep it.</p><div class="result-actions">${button('Export current backup','data-action="export"','secondary')}${button('Replace with this backup','data-action="confirm-import"')}</div>`);window.pendingImport=next;}catch(err){toast(err.message||'This backup could not be read. No data was changed.',true);}e.target.value='';}
 function logMatch(){modal(`<span class="eyebrow">IN-GAME TRANSFER JOURNAL</span><h2>Log a real match.</h2><form id="match-form" class="form-stack"><label>Outcome<select name="result"><option value="win">Win</option><option value="loss">Loss</option><option value="draw">Draw</option></select></label><label>${state.settings.game==='cs2'?'CS Rating after match':'RR within your current rank after match'}<input type="number" name="rating" required min="0" max="${state.settings.game==='cs2'?50000:100}" step="1"></label><label>Habit tested in this match<input name="note" maxlength="180" placeholder="e.g. Stopped before my first shot"></label><p class="small muted">Manual entry, not game-account verification. Rank changes need their own context.</p><button class="button primary" type="submit">Save match</button></form>`);$('#match-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.matches.push({game:state.settings.game,at:Date.now(),result:f.get('result'),rating:Number(f.get('rating')),note:String(f.get('note')).slice(0,180)});persist();closeModal();render();toast('Match saved to your transfer journal.');});}
 document.addEventListener('click',e=>{const b=e.target.closest('button,[data-page]');if(!b)return;if(b.dataset.theme){state.settings.theme=b.dataset.theme;persist();render();return;}if(b.dataset.accent){state.settings.accent=b.dataset.accent;persist();render();return;}if(b.dataset.weapon){chooseWeapon(b.dataset.weapon);return;}if(b.dataset.game){if(active||scenario){toast('Finish or exit the active session to change games.');return;}state.settings.game=b.dataset.game;persist();render();return;}if(b.dataset.page){location.hash=b.dataset.page;navigate(b.dataset.page);return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.drill){drillModal(b.dataset.drill);return;}if(b.dataset.benchmark){drillModal(b.dataset.benchmark,true);return;}if(b.dataset.start){beginDrill(b.dataset.start,b.dataset.fixed==='true');return;}if(b.dataset.scenario){startScenario(b.dataset.scenario);return;}if(b.dataset.answer!==undefined){answerQuestion(Number(b.dataset.answer));return;}if(b.dataset.scenarioChoice!==undefined){scenarioChoice(Number(b.dataset.scenarioChoice));return;}const a=b.dataset.action;if(!a)return;const actions={'native-practice':nativePractice,'toggle-theme':()=>{state.settings.theme=state.settings.theme==='light'?'dark':'light';applySettings();persist();if(!active&&!scenario)render();},adaptive:startAdaptive,'explore-map':openMap,'expand-range':expandRange,'world-jump':()=>range?.jump(),'world-aim':()=>range?.alternate(),armory:armory,'asset-credits':assetCredits,'world-reload':()=>range?.reload(),'world-crouch':()=>{if(!range)return;range.touchCrouch=!range.touchCrouch;b.setAttribute('aria-pressed',String(range.touchCrouch));},fieldwork:()=>modal(`<span class="eyebrow">FROM BROWSER TO GAME</span><h2>${active.skill.name}</h2><ol class="fieldwork-list">${TC.followThrough(active.skill.id,state.settings.game).map(x=>`<li>${x}</li>`).join('')}</ol><p class="small muted">These steps use the actual game. They do not produce a verified browser score.</p>`),method,help:()=>modal(`<div class="modal-icon">${icon('radar',30)}</div><span class="eyebrow">WELCOME TO STRATUM</span><h2>A better practice loop.</h2><div class="help-steps"><p><b>01 — Establish a baseline.</b> Each unmeasured skill starts with a fixed level 3 benchmark.</p><p><b>02 — Train the gaps.</b> Your queue adapts to your individual results. Harder means smaller targets, tighter timing, or more demanding decisions.</p><p><b>03 — Combine & apply.</b> Branching rounds connect decisions with mechanics. Test the same habits in the actual game.</p></div><p class="small muted">Your profile is saved only in this browser. Use Customize to set controls and export backups.</p>${button('Start my assessment','data-action="help-start"','primary full')}`),'help-start':()=>{closeModal();if(active||scenario){toast('Finish or exit the current session before starting a new assessment.');return;}startAdaptive();},'close-modal':closeModal,'clear-search':()=>{filter='All';search='';render();},'launch-range':launchRange,'launch-decisions':launchDecisions,'next-question':nextQuestion,'pause-session':pauseSession,'resume-session':resumeSession,fire:()=>{if(e.detail===0)range?.fire(e);},'exit-session':()=>{if(active?.explore){abandon();return;}if(active?.phase==='result'){abandon();return;}modal(`<h2>Exit this attempt?</h2><p>The incomplete drill will not affect your scores. Earlier completed drills are already saved.</p><div class="result-actions">${button('Keep training','data-action="close-modal"','secondary')}${button('Exit attempt','data-action="abandon"')}</div>`);pauseSession();},abandon:()=>{closeModal();abandon();},'next-focus':()=>{active=null;const id=queue.shift()||C.recommendation(state).skill.id;beginDrill(id,!C.summarize(state,id));},'finish-progress':()=>finishTo('progress'),'repeat-benchmark':()=>{const id=active.skill.id;active=null;beginDrill(id,true);},'scenario-next':scenarioNext,'scenario-aim':scenarioAim,'return-scenario':()=>{active=null;renderScenario();},'finish-scenarios':()=>finishTo('scenarios'),'exit-scenario':()=>modal(`<h2>Leave this round?</h2><p>Only completed live aim stages have been saved. Decision results are saved when the round finishes.</p><div class="result-actions">${button('Continue round','data-action="close-modal"','secondary')}${button('Leave round','data-action="abandon"')}</div>`),export:exportData,'confirm-import':()=>{if(window.pendingImport){state=window.pendingImport;delete window.pendingImport;persist();closeModal();render();toast('Training profile restored.');}},'log-match':logMatch,reset:()=>modal(`<h2>Reset training on this device?</h2><p>All saved results and match entries will be removed. Export a backup before resetting if you want to keep them. Your visual settings will stay.</p><div class="result-actions">${button('Export backup','data-action="export"','secondary')}${button('Reset results','data-action="confirm-reset"')}</div>`),'confirm-reset':()=>{state.sessions=[];state.matches=[];persist();closeModal();render();toast('Training data reset. Your next drill creates a new starting point.');}};actions[a]?.();});
 $('#mobile-game').addEventListener('change',e=>{if(active||scenario){e.target.value=state.settings.game;toast('Finish or exit the active session to change games.');return;}state.settings.game=e.target.value;persist();render();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});$('#modal').addEventListener('close',()=>{if(active?.phase==='paused')resumeSession();});
 document.addEventListener('keydown',e=>{if(active?.skill.type==='decision'&&active.phase==='running'&&!active.answered&&!$('#modal').open&&/^[1-4]$/.test(e.key)){answerQuestion(Number(e.key)-1);}if(e.code==='Escape'&&active?.skill.type==='decision'&&!$('#modal').open)pauseSession();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&active?.skill.type==='decision')pauseSession();});window.addEventListener('blur',()=>{if(active?.skill.type==='decision')pauseSession();});
 window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(!active&&!scenario)navigate(p);});
 if(!storageOK)$('#save-status').innerHTML='<i class="bad"></i> Saved data needs attention';applySettings();page=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
})();
